const item = $input.first().json;

// Normalize raw Apify / Facebook Ad Library fields
const libraryId = item.id || item.ad_archive_id || item.library_id || String(Math.floor(100000000000 + Math.random() * 900000000000));
const pageName = item.page_name || item.pageName || 'MySivi';
const fbPageId = item.page_id || item.pageId || 'mysivi.ai';
const followerCount = parseInt(item.page_like_count || item.follower_count || 120000, 10);
const category = item.page_categories || 'Education & Language Learning';

const startedDateStr = item.start_date || item.started_running_on || item.ad_delivery_start_time || new Date().toISOString().split('T')[0];
const startedRunningOn = startedDateStr.split('T')[0];

// Calculate longevity in days
const startedDate = new Date(startedRunningOn);
const today = new Date();
const diffTime = Math.abs(today.getTime() - startedDate.getTime());
const longevityDays = Math.max(1, Math.ceil(diffTime / (1000 * 60 * 60 * 24)));

const isActive = item.is_active !== undefined ? Boolean(item.is_active) : true;
const hasMultipleVersions = Boolean(item.has_multiple_versions || item.hasMultipleVersions || item.versions?.length > 1);
const platforms = item.publisher_platforms || item.platforms || ['facebook', 'instagram'];

const creativeUrl = item.creative_url || item.snapshot?.images?.[0]?.url || item.snapshot?.videos?.[0]?.video_preview_image_url || item.images?.[0] || 'https://images.unsplash.com/photo-1546410531-bb4caa6b424d?auto=format&fit=crop&w=800&q=80';
const creativeType = (item.snapshot?.videos?.length || item.videos?.length || item.creative_type === 'video') ? 'video' : 'image';

const rawText = item.primary_text || item.ad_creative_body || item.snapshot?.body?.text || item.body || item.raw_text || 'Master English speaking confidence with Arya, your 24/7 AI English teacher. Practice daily conversations and sound natural.';

return {
  json: {
    library_id: libraryId,
    page_name: pageName,
    fb_page_id: fbPageId,
    follower_count: followerCount,
    category,
    started_running_on: startedRunningOn,
    longevity_days: longevityDays,
    is_active: isActive,
    has_multiple_versions: hasMultipleVersions,
    platforms,
    creative_url: creativeUrl,
    creative_type: creativeType,
    raw_text: rawText,
    raw_snapshot: item
  }
};

