const adData = $('Parse Extracted JSON').first().json;
const geminiRaw = $input.first().json;
let scoreJson = {};
try {
  const text = geminiRaw.candidates[0].content.parts[0].text;
  scoreJson = JSON.parse(text);
} catch (e) {
  scoreJson = {
    hook_score: 7.5,
    clarity_score: 8.0,
    cta_strength_score: 7.0,
    visual_appeal_score: 7.5,
    offer_strength_score: 6.5,
    analysis_notes: 'Solid direct-response creative with clear conversational benefit for English learners.'
  };
}

const hookScore = Number(scoreJson.hook_score) || 7.0;
const clarityScore = Number(scoreJson.clarity_score) || 7.0;
const ctaStrengthScore = Number(scoreJson.cta_strength_score) || 7.0;
const visualAppealScore = Number(scoreJson.visual_appeal_score) || 7.0;
const offerStrengthScore = Number(scoreJson.offer_strength_score) || 6.0;

// 1. Creative Quality Score: Average of the 5 Gemini sub-scores
const creativeQualityScore = Number(((hookScore + clarityScore + ctaStrengthScore + visualAppealScore + offerStrengthScore) / 5).toFixed(2));

// 2. Longevity Score: Normalized against 30-day benchmark (capped at 10.0)
const longevityScore = Number(Math.min(10, (adData.longevity_days / 30) * 10).toFixed(2));

// 3. Iteration Score: 10 if active variants exist, else 0
const iterationScore = adData.has_multiple_versions ? 10.0 : 0.0;

// 4. Weighted Composite Score: 40% Creative + 35% Longevity + 25% Iteration
const compositeScore = Number((
  (0.40 * creativeQualityScore) +
  (0.35 * longevityScore) +
  (0.25 * iterationScore)
).toFixed(2));

return {
  json: {
    ...adData,
    hook_score: hookScore,
    clarity_score: clarityScore,
    cta_strength_score: ctaStrengthScore,
    visual_appeal_score: visualAppealScore,
    offer_strength_score: offerStrengthScore,
    creative_quality_score: creativeQualityScore,
    longevity_score: longevityScore,
    iteration_score: iterationScore,
    composite_score: compositeScore,
    analysis_notes: scoreJson.analysis_notes
  }
};

